package org.chromium.content_public.browser; import java.util.*; import org.chromium.services.media_session.MediaPosition; public class MediaSession {public List<MediaSessionObserver> observers=new ArrayList<>();public boolean controllable=true,suspended;public int toggles;public long target=-1;public MediaPosition position=new MediaPosition(300000,30000,1,0); public static MediaSession fromWebContents(WebContents c){return c.session;} public boolean isControllable(){return controllable;} public void resume(int t){toggles++;suspended=false;} public void suspend(int t){toggles++;suspended=true;} public void seekTo(long t){target=t;} public void addObserver(MediaSessionObserver o){observers.add(o);o.mediaSessionStateChanged(controllable,suspended);o.mediaSessionPositionChanged(position);o.mediaSessionActionsChanged(Set.of(1));} public void removeObserver(MediaSessionObserver o){observers.remove(o);} public void destroy(){for(var o:List.copyOf(observers))o.mediaSessionDestroyed();observers.clear();} }
